/**
 * MorphoNews Layout: 遷移型フルイド・ストリーム・マージ
 * Generation: #74
 * Evolution: Horizontal Fluid Merge + @starting-style + Scroll-driven Convergence
 */

:root {
    --layout-max-width: 1400px;
    --layout-news-columns: 1fr 1fr;
    --layout-card-gap: 0px;
    --layout-card-direction: row;
    --layout-animation-style: fluid-stream-merge;
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 5rem auto;
    padding: 0 2rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    position: relative;
}

/* 中央のストリームライン */
#news-container::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 1px;
    background: linear-gradient(to bottom, transparent, var(--morph-accent-primary), transparent);
    z-index: 10;
    opacity: 0.3;
}

.news-card {
    position: relative;
    height: 450px;
    container-type: size;
    view-timeline-name: --card-stream;
    view-timeline-axis: block;
    margin-bottom: -50px; /* 重なりを許容 */
}

/* 奇数番目：左から右へ */
.news-card:nth-child(odd) {
    padding-right: 2rem;
    animation: merge-left both linear;
    animation-timeline: --card-stream;
    animation-range: entry 0% exit 100%;
}

/* 偶数番目：右から左へ */
.news-card:nth-child(even) {
    padding-left: 2rem;
    margin-top: 150px;
    animation: merge-right both linear;
    animation-timeline: --card-stream;
    animation-range: entry 0% exit 100%;
}

@keyframes merge-left {
    0% { transform: translateX(-100px); opacity: 0.3; filter: grayscale(1); }
    50% { transform: translateX(0); opacity: 1; filter: grayscale(0); }
    100% { transform: translateX(-50px); opacity: 0.3; }
}

@keyframes merge-right {
    0% { transform: translateX(100px); opacity: 0.3; filter: grayscale(1); }
    50% { transform: translateX(0); opacity: 1; filter: grayscale(0); }
    100% { transform: translateX(50px); opacity: 0.3; }
}

.news-card-body {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    background: rgba(var(--morph-bg-secondary-rgb), 0.6);
    backdrop-filter: blur(20px);
    padding: 3rem;
    border: 1px solid rgba(var(--morph-accent-primary-rgb), 0.1);
    transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
    position: relative;
    overflow: hidden;
}

